// Per-node run state (src/run-rows.mjs; research/review-20261007/04-efficiency-rust.md finding 2, R-9).
// Development/diagnostic evidence: synthetic local capabilities, no model, no network.
//   - compatibility: a workspace written by the whole-run store (tests/fixtures/store-rows/legacy-run.json, generated by that store) still opens,
//     loads, verifies, and is split into rows by its first write; the same workflow on the current store yields the same record and events;
//   - the row layer: lazy drafts, compare-and-swap per row, per-row and total byte bounds, atomic commit with the chain event;
//   - cost: an update touches the rows it changed, so its cost does not grow with the run, and the runtime never re-reads a whole run in the loop.
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { DatabaseSync } from 'node:sqlite';
import { Store } from '../src/store.mjs';
import { Runtime } from '../src/runtime.mjs';
import { createDefaultRegistry } from '../src/capabilities.mjs';
import { validateWorkflow } from '../src/validate.mjs';
import { verifyRun } from '../src/verify-run.mjs';
import { canonical, digest } from '../src/data.mjs';
import { MATERIALIZE, STATE_BYTES, STATE_LIMITS } from '../src/run-rows.mjs';

const fixture = JSON.parse(readFileSync(new URL('./fixtures/store-rows/legacy-run.json', import.meta.url), 'utf8'));
const scratch = t => { const dir = mkdtempSync(path.join(tmpdir(), 'foundry-rows-')); t.after(() => rmSync(dir, { recursive: true, force: true })); return dir; };
const opened = (t, dir = scratch(t)) => { const store = new Store(dir); t.after(() => { try { store.close(); } catch { /* already closed */ } }); return store; };
const ref = $ref => ({ $ref });
const base = (nodes, acceptance, budget = {}) => ({
  schemaVersion: '1.0', id: 'RowsProbe', version: 1, title: 'Run state rows probe', domain: 'diagnostic', goal: 'Exercise per-node run state with synthetic local inputs.',
  envelope: { assumptions: ['Synthetic local capabilities only'], risks: [], successCriteria: ['The run finishes.'] },
  budget: { maxSteps: 500, maxConcurrency: 4, maxDurationMs: 60000, maxCost: 0, ...budget }, nodes, acceptance
});
const echo = (id, args = { value: 1 }, needs = []) => ({ id, kind: 'task', needs, description: `Echo ${id}`, tool: 'core.identity', args, timeoutMs: 5000, retry: { maxAttempts: 1 } });
const chain = n => base(Array.from({ length: n }, (_, i) => echo(`t${i}`, { value: i }, i ? [`t${i - 1}`] : [])), [{ op: 'eq', left: ref(`nodes.t${n - 1}.value`), right: n - 1 }]);
function environment(t, workflow, input = {}) {
  const dir = scratch(t), store = opened(t, dir), registry = createDefaultRegistry();
  const valid = validateWorkflow(workflow, { registry });
  assert.equal(valid.valid, true, JSON.stringify(valid.errors));
  store.saveWorkflow(workflow);
  const runtime = new Runtime(store, registry, {});
  return { dir, store, runtime, run: runtime.create(workflow, input) };
}
const count = (store, table, id) => store.db.prepare(`SELECT COUNT(*) AS n FROM ${table} WHERE ${table === 'runs' ? 'id' : 'run_id'}=?`).get(id).n;

// ---- a workspace written by the whole-run store -----------------------------------------------------------------------------------------------
const OLD_SCHEMA = `CREATE TABLE workflows(hash TEXT PRIMARY KEY, id TEXT NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL, UNIQUE(id,version));
  CREATE TABLE heads(id TEXT PRIMARY KEY, hash TEXT NOT NULL); CREATE TABLE runs(id TEXT PRIMARY KEY, body TEXT NOT NULL);
  CREATE TABLE events(run_id TEXT NOT NULL, seq INTEGER NOT NULL, body TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(run_id,seq));
  CREATE TABLE decisions(id TEXT PRIMARY KEY, run_id TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL); CREATE INDEX decisions_run ON decisions(run_id);`;
/** The fixture's workspace with the OLD tables only (no rev/bytes columns, no run_* tables), then opened by the current Store. */
function legacyWorkspace(t) {
  const dir = scratch(t);
  const state = path.join(dir, '.foundry'); // the Store would create it; the old tables go in first
  rmSync(state, { recursive: true, force: true });
  new Store(dir).close(); rmSync(path.join(state, 'foundry.sqlite'), { force: true }); rmSync(path.join(state, 'foundry.sqlite-wal'), { force: true }); rmSync(path.join(state, 'foundry.sqlite-shm'), { force: true });
  const raw = new DatabaseSync(path.join(state, 'foundry.sqlite'));
  raw.exec(OLD_SCHEMA);
  const w = fixture.workflow;
  raw.prepare('INSERT INTO workflows VALUES(?,?,?,?,?)').run(w.hash, w.id, w.version, w.body, w.created);
  raw.prepare('INSERT INTO heads VALUES(?,?)').run(w.id, w.hash);
  raw.prepare('INSERT INTO runs VALUES(?,?)').run(fixture.runId, fixture.runBody);
  for (const e of fixture.events) raw.prepare('INSERT INTO events VALUES(?,?,?,?)').run(fixture.runId, e.seq, e.body, e.hash);
  for (const d of fixture.decisions) raw.prepare('INSERT INTO decisions VALUES(?,?,?,?)').run(d.id, fixture.runId, d.kind, d.body);
  raw.close();
  return { dir, store: opened(t, dir) };
}
const record = JSON.parse(fixture.runBody);

test('legacy: a workspace written by the whole-run store opens (its runs table gains rev and bytes) and loads the record exactly as stored', t => {
  const { store } = legacyWorkspace(t);
  assert.deepEqual(store.db.prepare('PRAGMA table_info(runs)').all().map(c => c.name), ['id', 'body', 'rev', 'bytes']);
  assert.equal(store.db.prepare('PRAGMA user_version').get().user_version, 2);
  assert.deepEqual(store.run(fixture.runId), record, 'the record is returned as it was written');
  assert.equal(count(store, 'run_nodes', fixture.runId), 0, 'reading does not migrate');
  assert.deepEqual(store.rows.header(fixture.runId), Object.fromEntries(Object.entries(record).filter(([key]) => !['input', 'nodes', 'outputs', 'frames'].includes(key))));
  assert.equal(store.events(fixture.runId).length, fixture.events.length, 'its hash chain verifies');
  assert.deepEqual(store.runs().map(r => r.id), [fixture.runId]);
  const report = verifyRun(store, fixture.runId);
  assert.equal(report.ok, true, JSON.stringify(report.findings));
  assert.equal(count(store, 'run_nodes', fixture.runId), 0, 'verifying does not migrate either');
});

test('legacy: the first write splits the record into rows; the record, the chain and the stored state size carry over', t => {
  const { store } = legacyWorkspace(t);
  const before = store.run(fixture.runId);
  const updated = store.updateRun(fixture.runId, r => { r.extra.touched = true; }, { type: 'audit.rows-test' });
  const body = JSON.parse(store.db.prepare('SELECT body FROM runs WHERE id=?').get(fixture.runId).body);
  for (const key of ['nodes', 'outputs', 'frames', 'input']) assert.equal(Object.hasOwn(body, key), false, `${key} left the header`);
  const nodes = Object.keys(before.nodes).length + Object.values(before.frames).reduce((n, f) => n + Object.keys(f.nodes).length, 0);
  assert.equal(count(store, 'run_nodes', fixture.runId), nodes);
  assert.equal(count(store, 'run_frames', fixture.runId), Object.keys(before.frames).length);
  assert.equal(count(store, 'run_input', fixture.runId), 1);
  const expected = structuredClone(before); expected.extra.touched = true; expected.updatedAt = updated.updatedAt; expected.eventHead = updated.eventHead;
  assert.deepEqual(updated, expected, 'nothing but the change differs');
  assert.deepEqual(store.run(fixture.runId), expected);
  assert.equal(store.events(fixture.runId).length, fixture.events.length + 1);
  assert.equal(store.events(fixture.runId).at(-1).type, 'audit.rows-test');
  assert.ok(store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(fixture.runId).bytes > 1000, 'the stored size is kept');
});

test('legacy: migrateRuns splits every whole-run record, once', t => {
  const { store } = legacyWorkspace(t);
  assert.deepEqual(store.migrateRuns(), { migrated: 1, runs: 1 });
  assert.deepEqual(store.run(fixture.runId), record, 'the migrated record is the record');
  assert.equal(store.events(fixture.runId).length, fixture.events.length, 'and the chain did not change');
  assert.deepEqual(store.migrateRuns(), { migrated: 0, runs: 1 });
  assert.equal(verifyRun(store, fixture.runId).ok, true);
});

test('legacy: a whole record written into runs.body (what an editor of the checkpoint does) wins over stale rows and is split again by the next write', t => {
  const { store, run } = environment(t, chain(3));
  const finish = () => store.updateRun(run.id, r => { r.nodes.t0 = { kind: 'task', status: 'completed' }; r.outputs.t0 = { value: 0 }; }, { type: 'probe' });
  finish();
  const forged = store.run(run.id); forged.nodes.t0.status = 'forged'; forged.steps = 77;
  store.db.prepare('UPDATE runs SET body=? WHERE id=?').run(canonical(forged), run.id);
  assert.equal(store.run(run.id).nodes.t0.status, 'forged', 'the edited record is what is read');
  assert.equal(store.rows.header(run.id).steps, 77);
  store.updateRun(run.id, r => { r.cost = 1; }, { type: 'probe' });
  const back = store.run(run.id);
  assert.equal(back.nodes.t0.status, 'forged'); assert.equal(back.cost, 1);
  assert.equal(store.db.prepare("SELECT status FROM run_nodes WHERE run_id=? AND node_key='root/t0'").get(run.id).status, 'forged', 'the stale row was replaced');
  assert.equal(Object.hasOwn(JSON.parse(store.db.prepare('SELECT body FROM runs WHERE id=?').get(run.id).body), 'nodes'), false);
});

test('legacy: `foundry inspect` prints the same thing before and after `foundry migrate-store`, and migrating twice changes nothing', t => {
  const { dir, store } = legacyWorkspace(t);
  store.close();
  const bin = new URL('../bin/foundry.mjs', import.meta.url).pathname;
  const cli = (...args) => { const r = spawnSync(process.execPath, [bin, ...args, '--workspace', dir], { encoding: 'utf8', timeout: 30000, env: { PATH: process.env.PATH, NODE_NO_WARNINGS: '1' } }); assert.equal(r.status, 0, r.stderr); return r.stdout; };
  const before = cli('inspect', fixture.runId);
  assert.equal(JSON.parse(before).id, fixture.runId); assert.equal(JSON.parse(before).events.length, fixture.events.length);
  assert.deepEqual(JSON.parse(cli('migrate-store')), { workspace: dir, migrated: 1, runs: 1 });
  assert.equal(cli('inspect', fixture.runId), before, 'the same output once the record is in rows');
  assert.deepEqual(JSON.parse(cli('migrate-store')), { workspace: dir, migrated: 0, runs: 1 });
  const verify = JSON.parse(cli('verify-run', fixture.runId));
  assert.equal(verify.ok, true, JSON.stringify(verify.findings));
  const missing = spawnSync(process.execPath, [bin, 'migrate-store', '--workspace', path.join(dir, 'nowhere')], { encoding: 'utf8', timeout: 30000, env: { PATH: process.env.PATH, NODE_NO_WARNINGS: '1' } });
  assert.notEqual(missing.status, 0); assert.match(missing.stderr + missing.stdout, /NO_STATE/);
});

// ---- the current store gives the record and events the whole-run store gave ----------------------------------------------------------------------
// Times, ids and hashes differ between two runs; everything else about a finished run of the fixture's workflow must not.
const VARYING = new Set(['id', 'createdAt', 'updatedAt', 'deadline', 'engineHash', 'startedAt', 'completedAt', 'at', 'idempotencyKey', 'eventHead', 'identity', 'sampleSalt', 'hash', 'previousHash', 'token']);
const scrub = value => Array.isArray(value) ? value.map(scrub) : value && typeof value === 'object'
  ? Object.fromEntries(Object.entries(value).filter(([key]) => !VARYING.has(key)).sort(([a], [b]) => a < b ? -1 : 1).map(([key, item]) => [key, scrub(item)])) : value;

test('compatibility: the same workflow and input on the current store produce the whole-run store\'s record, values and events', async t => {
  const workflow = JSON.parse(fixture.workflow.body), dir = scratch(t), store = opened(t, dir), registry = createDefaultRegistry();
  store.saveWorkflow(workflow);
  const runtime = new Runtime(store, registry, {});
  const run = runtime.create(workflow, { notes: 'legacy store', items: ['a', 'b', 'c'] });
  const result = await runtime.execute(run.id);
  assert.equal(result.status, 'succeeded');
  assert.deepEqual(scrub(result), scrub(record), 'the record');
  assert.deepEqual(Object.keys(result).sort(), Object.keys(record).sort());
  assert.deepEqual(store.run(run.id), result, 'what execute returns is what is stored');
  const wanted = fixture.events.map(e => JSON.parse(e.body)), got = store.events(run.id);
  const key = e => `${e.type} ${e.nodeKey ?? ''}`;
  assert.deepEqual(got.map(key).sort(), wanted.map(key).sort(), 'the same events (concurrent items may interleave differently)');
  const fields = e => Object.keys(e).filter(name => name !== 'hash').sort().join();
  assert.deepEqual(got.map(fields).sort(), wanted.map(fields).sort(), 'with the same fields');
  assert.deepEqual(got.filter(e => !e.nodeKey?.includes(':')).map(key), wanted.filter(e => !e.nodeKey?.includes(':')).map(key), 'and the root order');
  assert.equal(verifyRun(store, run.id).ok, true);
  assert.deepEqual(got.map(e => e.type).slice(-2), ['run.verdict', 'run.succeeded']);
});

// ---- the layout -------------------------------------------------------------------------------------------------------------------------------
test('layout: a run is a header, an input row, frame rows and node rows; store.run() puts the record back together in key order', async t => {
  const workflow = JSON.parse(fixture.workflow.body);
  const dir = scratch(t), store = opened(t, dir);
  store.saveWorkflow(workflow);
  const runtime = new Runtime(store, createDefaultRegistry(), {});
  const run = runtime.create(workflow, { notes: 'n', items: ['a', 'b', 'c'] });
  const finished = await runtime.execute(run.id);
  const header = JSON.parse(store.db.prepare('SELECT body FROM runs WHERE id=?').get(run.id).body);
  assert.deepEqual(Object.keys(header).filter(key => ['input', 'nodes', 'outputs', 'frames'].includes(key)), []);
  assert.equal(header.status, 'succeeded'); assert.deepEqual(header.eventHead, finished.eventHead);
  assert.deepEqual(JSON.parse(store.db.prepare('SELECT body FROM run_input WHERE run_id=?').get(run.id).body), { notes: 'n', items: ['a', 'b', 'c'] });
  assert.deepEqual(store.db.prepare('SELECT frame_key FROM run_frames WHERE run_id=? ORDER BY frame_key').all(run.id).map(r => r.frame_key), ['root/each:0', 'root/each:1', 'root/each:2']);
  assert.deepEqual(store.db.prepare('SELECT node_key, status FROM run_nodes WHERE run_id=? ORDER BY node_key').all(run.id).map(r => `${r.node_key}=${r.status}`),
    ['root/check=completed', 'root/each=completed', 'root/each:0/echo=completed', 'root/each:1/echo=completed', 'root/each:2/echo=completed', 'root/first=completed']);
  assert.deepEqual(Object.keys(finished.nodes), ['check', 'each', 'first'], 'key order is the stored (sorted) order');
  const sortedKeys = value => Array.isArray(value) ? value.every(sortedKeys) : !value || typeof value !== 'object' || (Object.keys(value).every((key, i, all) => !i || all[i - 1] < key) && Object.values(value).every(sortedKeys));
  assert.equal(sortedKeys(finished), true, 'every object of the record has its keys in sorted order, as when it was one canonical blob (printed output keeps its order)');
  assert.deepEqual(Object.keys(finished.frames), ['root/each:0', 'root/each:1', 'root/each:2']);
  assert.equal(store.db.prepare("SELECT output FROM run_nodes WHERE run_id=? AND node_key='root/check'").get(run.id).output, canonical({ passed: true }));
  // The columns the runtime queries repeat the state they were taken from.
  for (const row of store.db.prepare('SELECT status, label, body FROM run_nodes WHERE run_id=? AND body IS NOT NULL').all(run.id)) {
    const state = JSON.parse(row.body);
    assert.equal(row.status, state.status); assert.equal(row.label, state.outputLabel && state.outputLabel !== 'trusted' ? state.outputLabel : null);
  }
});

test('layout: the targeted reads return what the record holds', async t => {
  const { store, runtime, run } = environment(t, base([echo('a', { value: 'x' }), { ...echo('b', { value: ref('nodes.a.value') }, ['a']), onError: 'continue' }], [{ op: 'eq', left: ref('nodes.b.value'), right: 'x' }]), { q: 1 });
  const finished = await runtime.execute(run.id), rows = store.rows;
  assert.deepEqual(rows.header(run.id), Object.fromEntries(Object.entries(finished).filter(([key]) => !['input', 'nodes', 'outputs', 'frames'].includes(key))));
  assert.deepEqual(rows.nodeState(run.id, 'root', 'a'), finished.nodes.a);
  assert.equal(rows.nodeState(run.id, 'root', 'nope'), undefined);
  assert.deepEqual(rows.nodeStates(run.id, 'root', ['a', 'b', 'nope']), finished.nodes);
  assert.deepEqual(rows.nodeOutput(run.id, 'root', 'a'), finished.outputs.a);
  assert.equal(rows.nodeOutput(run.id, 'root', 'nope'), undefined);
  assert.deepEqual(rows.frameOutputs(run.id, 'root'), finished.outputs);
  assert.deepEqual([...rows.statuses(run.id, 'root')], [['a', 'completed'], ['b', 'completed']]);
  assert.equal(rows.anyWithStatus(run.id, 'uncertain', 'awaiting_human'), false); assert.equal(rows.anyWithStatus(run.id, 'completed'), true);
  assert.deepEqual(rows.withStatus(run.id, 'completed').map(r => `${r.frameKey}/${r.nodeId}`), ['root/a', 'root/b']);
  assert.equal(rows.frame(run.id, 'root/none:0'), undefined);
  assert.deepEqual(rows.labels(run.id, 'root'), new Map());
  assert.throws(() => rows.header('no-such-run'), { code: 'NOT_FOUND' });
});

test('layout: labels and frame labels are index lookups on the non-trusted output label', t => {
  const { store, run } = environment(t, chain(1));
  store.updateRun(run.id, r => {
    r.nodes.a = { status: 'completed', outputLabel: 'untrusted:web' }; r.nodes.b = { status: 'completed', outputLabel: 'untrusted:mail+web' }; r.nodes.c = { status: 'completed' };
    r.frames['root/m:0'] = { nodes: { x: { status: 'completed', outputLabel: 'untrusted:file' } }, outputs: {}, contextHash: 'h' };
    r.frames['root/m:1'] = { nodes: { x: { status: 'completed' } }, outputs: {}, contextHash: 'h' };
    r.frames['root/m:1/in:0'] = { nodes: { y: { status: 'completed', outputLabel: 'untrusted:deep' } }, outputs: {}, contextHash: 'h' };
    r.frames['root/mm:0'] = { nodes: { z: { status: 'completed', outputLabel: 'untrusted:other-map' } }, outputs: {}, contextHash: 'h' };
  }, { type: 'probe' });
  const rows = store.rows;
  assert.deepEqual([...rows.labels(run.id, 'root')].sort(), [['a', 'untrusted:web'], ['b', 'untrusted:mail+web']]);
  assert.deepEqual([...rows.labels(run.id, 'root', ['a', 'c', 'nope'])], [['a', 'untrusted:web']]);
  assert.deepEqual(rows.frameLabels(run.id, 'root/m:').sort(), ['untrusted:deep', 'untrusted:file'], 'all iterations of one map, not the map named m2');
  assert.deepEqual(rows.frameLabels(run.id, 'root/m:1', { exact: true }), ['untrusted:deep'], 'one iteration and its descendants');
  assert.deepEqual(rows.frameLabels(run.id, 'root/m:0', { exact: true }), ['untrusted:file']);
  assert.deepEqual(rows.frameLabels(run.id, 'root/m:', { exact: false }).includes('untrusted:other-map'), false);
});

// ---- drafts -------------------------------------------------------------------------------------------------------------------------------------
test('draft: a mutation reads and writes the record through lazily loaded rows', t => {
  const { store, run } = environment(t, chain(1), { a: 1 });
  store.updateRun(run.id, r => {
    r.status = 'running';
    r.nodes.x = { status: 'running', kind: 'task' }; r.outputs.x = { v: 1 }; r.outputs.nul = null;
    r.frames['root/m:0'] = { nodes: {}, outputs: {}, contextHash: 'h' };
    r.frames['root/m:0'].nodes.y = { status: 'completed' }; r.frames['root/m:0'].outputs.y = [1, 2]; r.frames['root/m:0'].result = 'completed';
  }, { type: 'probe.one' });
  assert.deepEqual(store.run(run.id).outputs, { nul: null, x: { v: 1 } }, 'a JSON null output is an output');
  store.updateRun(run.id, r => {
    assert.deepEqual(Object.keys(r.nodes), ['x']); assert.deepEqual(Object.keys(r.outputs), ['nul', 'x']);
    assert.equal('x' in r.nodes, true); assert.equal('nope' in r.nodes, false); assert.equal(Object.hasOwn(r.outputs, 'nul'), true);
    assert.equal(r.nodes.nope, undefined); assert.equal(r.frames['root/none:0'], undefined); assert.equal('root' in r.frames, false);
    assert.deepEqual(Object.keys(r.frames), ['root/m:0']);
    assert.equal(r.frames['root/m:0'].nodes.y.status, 'completed'); assert.equal(r.frames['root/m:0'].result, 'completed');
    assert.deepEqual(r.input, { a: 1 });
    assert.deepEqual(JSON.parse(JSON.stringify(r.frames)), { 'root/m:0': { contextHash: 'h', nodes: { y: { status: 'completed' } }, outputs: { y: [1, 2] }, result: 'completed' } });
    r.nodes.x.status = 'completed';                       // a nested edit of a loaded state
    Object.assign(r.frames['root/m:0'], { result: 'failed', error: { code: 'E' } });
    delete r.outputs.nul; delete r.frames['root/m:0'].nodes.y;
    r.nodes.fresh = { status: 'pending' };
    r.steps += 2;
    assert.equal(r[STATE_BYTES] > 0, true);
  }, { type: 'probe.two' });
  const record = store.run(run.id);
  assert.deepEqual(record.nodes, { fresh: { status: 'pending' }, x: { kind: 'task', status: 'completed' } });
  assert.deepEqual(record.outputs, { x: { v: 1 } });
  assert.deepEqual(record.frames, { 'root/m:0': { contextHash: 'h', error: { code: 'E' }, nodes: {}, outputs: { y: [1, 2] }, result: 'failed' } });
  assert.equal(record.steps, 2); assert.deepEqual(record.input, { a: 1 });
  assert.equal(count(store, 'run_nodes', run.id), 3, 'a row with neither state nor output is gone; one with an output only stays');
  // whole-map replacement, frame removal and the input
  store.updateRun(run.id, r => { r.nodes = { only: { status: 'done' } }; delete r.frames['root/m:0']; r.input = { b: 2 }; r.outputs = {}; }, { type: 'probe.three' });
  const after = store.run(run.id);
  assert.deepEqual([after.nodes, after.outputs, after.frames, after.input], [{ only: { status: 'done' } }, {}, {}, { b: 2 }]);
  assert.equal(count(store, 'run_frames', run.id), 0); assert.equal(count(store, 'run_nodes', run.id), 1);
  assert.equal(store.updateRun(run.id, () => {}, { type: 'probe.noop' }, { result: 'header' }).nodes, undefined, 'the header result carries no rows');
  assert.throws(() => store.updateRun('no-such-run', () => {}, []), { code: 'NOT_FOUND' });
});

test('draft: the whole run is available to code that enumerates it (the verdict seal), including what this update changed', async t => {
  const { store, runtime, run } = environment(t, chain(4));
  const finished = await runtime.execute(run.id);
  store.updateRun(run.id, r => {
    r.outputs.t0 = { value: 'edited' };
    const plain = r[MATERIALIZE]();
    assert.equal(plain.outputs.t0.value, 'edited'); assert.deepEqual(plain.frames, {}); assert.deepEqual(plain.input, finished.input);
    assert.deepEqual(Object.keys(plain.nodes), ['t0', 't1', 't2', 't3']);
    assert.equal(Object.getPrototypeOf(plain.nodes), Object.prototype, 'plain objects, not views');
  }, { type: 'probe' });
});

test('draft: only the rows a mutation changed are written (one node of a large run costs one node row, the header and the event)', t => {
  const { store, run } = environment(t, chain(1));
  store.updateRun(run.id, r => { for (let i = 0; i < 400; i++) { r.nodes[`n${i}`] = { status: 'completed', i }; r.outputs[`n${i}`] = { value: i }; } }, { type: 'probe.fill' });
  const changes = () => store.db.prepare('SELECT total_changes() AS n').get().n;
  const before = changes();
  store.updateRun(run.id, r => { r.nodes.n200.status = 'changed'; }, { type: 'probe.one' });
  assert.equal(changes() - before, 3, 'one node row + the event + the header');
  const second = changes();
  store.updateRun(run.id, r => { assert.equal(r.nodes.n7.status, 'completed'); assert.deepEqual(r.outputs.n9, { value: 9 }); }, { type: 'probe.reads' });
  assert.equal(changes() - second, 2, 'reading rows writes nothing: the event + the header');
  assert.equal(store.run(run.id).nodes.n200.status, 'changed');
});

// ---- compare-and-swap, bounds and atomicity --------------------------------------------------------------------------------------------------------
test('compare-and-swap: a row or header that changed under an update is not overwritten, and nothing of the update is kept', t => {
  const { store, run } = environment(t, chain(1));
  store.updateRun(run.id, r => { r.nodes.a = { status: 'running' }; r.outputs.a = { v: 1 }; }, { type: 'probe.setup' });
  const events = () => store.db.prepare('SELECT COUNT(*) AS n FROM events WHERE run_id=?').get(run.id).n, wasEvents = events();
  const rev = key => store.db.prepare('SELECT rev FROM run_nodes WHERE run_id=? AND node_key=?').get(run.id, key).rev;
  assert.equal(rev('root/a'), 0);
  assert.throws(() => store.updateRun(run.id, r => {
    r.nodes.a.status = 'mine';
    store.db.prepare("UPDATE run_nodes SET rev=rev+1, status='theirs' WHERE run_id=? AND node_key='root/a'").run(run.id); // a competing writer
  }, { type: 'probe.lost' }), { code: 'STATE_CONFLICT' });
  assert.equal(events(), wasEvents, 'no event');
  assert.equal(store.db.prepare("SELECT status FROM run_nodes WHERE run_id=? AND node_key='root/a'").get(run.id).status, 'running', 'the whole update rolled back, the competing write with it');
  assert.throws(() => store.updateRun(run.id, r => {
    r.steps = 9; store.db.prepare('UPDATE runs SET rev=rev+1 WHERE id=?').run(run.id);
  }, { type: 'probe.header' }), { code: 'STATE_CONFLICT' });
  assert.throws(() => store.updateRun(run.id, r => {
    r.nodes.brand_new = { status: 'x' };
    store.db.prepare("INSERT INTO run_nodes(run_id,node_key,frame_key,node_id,status,body,rev) VALUES(?,'root/brand_new','root','brand_new','y','{}',0)").run(run.id);
  }, { type: 'probe.insert' }), { code: 'STATE_CONFLICT' }, 'a row created by someone else');
  assert.throws(() => store.updateRun(run.id, r => { delete r.nodes.a; delete r.outputs.a; store.db.prepare("UPDATE run_nodes SET rev=rev+1 WHERE run_id=? AND node_key='root/a'").run(run.id); }, []), { code: 'STATE_CONFLICT' });
  assert.equal(store.run(run.id).steps, 0);
  assert.equal(store.updateRun(run.id, r => { r.steps = 1; }, { type: 'probe.ok' }).steps, 1, 'and the store is usable afterwards');
  assert.equal(rev('root/a'), 0, 'a row that was not written keeps its revision');
  store.updateRun(run.id, r => { r.nodes.a.status = 'done'; }, { type: 'probe.rev' });
  assert.equal(rev('root/a'), 1);
});

test('bounds: each row, the header and the whole run have a byte bound; a refused update changes nothing', t => {
  const { store, run } = environment(t, chain(1));
  const was = () => store.db.prepare('SELECT COUNT(*) AS n FROM events WHERE run_id=?').get(run.id).n;
  assert.deepEqual(Object.keys(STATE_LIMITS).sort(), ['budgetBytes', 'frameBytes', 'headerBytes', 'inputBytes', 'nodeOutputBytes', 'nodeStateBytes', 'totalBytes']);
  assert.equal(STATE_LIMITS.budgetBytes, 10 * 1024 * 1024); assert.equal(STATE_LIMITS.totalBytes, 12 * 1024 * 1024);
  const refused = (mutate, what) => { const events = was(); assert.throws(() => store.updateRun(run.id, mutate, { type: 'probe.big' }), { code: 'DATA_LIMIT' }, what); assert.equal(was(), events, `${what}: no event`); };
  store.limits.nodeOutputBytes = 1000; refused(r => { r.outputs.big = { text: 'x'.repeat(2000) }; }, 'an output over its row bound');
  store.updateRun(run.id, r => { r.outputs.ok = { text: 'x'.repeat(500) }; }, { type: 'probe.ok' });
  store.limits.nodeStateBytes = 1000; refused(r => { r.nodes.big = { note: 'x'.repeat(2000) }; }, 'a node state over its row bound');
  store.limits.frameBytes = 100; refused(r => { r.frames['root/f:0'] = { nodes: {}, outputs: {}, contextHash: 'h'.repeat(500) }; }, 'a frame over its bound');
  store.limits.headerBytes = 3000; refused(r => { r.extra.pad = 'x'.repeat(4000); }, 'a header over its bound');
  store.limits.inputBytes = 100; refused(r => { r.input = { pad: 'x'.repeat(500) }; }, 'an input over its bound');
  Object.assign(store.limits, STATE_LIMITS);
  const used = store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(run.id).bytes;
  store.limits.totalBytes = used + 600;
  refused(r => { r.outputs.more = { text: 'x'.repeat(2000) }; }, 'a run over its total bound (every row small)');
  store.updateRun(run.id, r => { r.outputs.small = { text: 'y'.repeat(100) }; }, { type: 'probe.fits' });
  store.updateRun(run.id, r => { delete r.outputs.ok; delete r.outputs.small; }, { type: 'probe.shrinks' });
  assert.ok(store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(run.id).bytes <= used, 'deleting rows gives the bytes back');
  const exact = JSON.stringify(store.run(run.id)).length;
  assert.ok(Math.abs(store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(run.id).bytes - exact) < exact * 0.2, 'the counter tracks the size of the record');
});

test('bounds: the runtime stops starting nodes once the run is over the state budget (STATE_BUDGET), leaving room for the failure receipt', async t => {
  const { store, runtime, run } = environment(t, chain(8));
  store.limits.budgetBytes = 2500;
  const result = await runtime.execute(run.id);
  assert.equal(result.status, 'failed'); assert.equal(result.error.code, 'STATE_BUDGET');
  assert.equal(result.verdict.verdict, 'harness_fault');
  const started = Object.keys(result.nodes).length;
  assert.ok(started >= 1 && started < 8, `${started} nodes started before the budget stopped the run`);
  assert.ok(store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(run.id).bytes <= STATE_LIMITS.totalBytes);
});

test('atomicity: a process killed after the node rows and the event were written but before the commit leaves the run as it was', t => {
  const { dir, store, run } = environment(t, chain(1));
  store.updateRun(run.id, r => { r.nodes.a = { status: 'running' }; r.outputs.a = { v: 1 }; r.steps = 1; }, { type: 'probe.setup' });
  const before = { record: store.run(run.id), events: store.events(run.id) };
  store.close();
  const source = `
    import { Store } from ${JSON.stringify(new URL('../src/store.mjs', import.meta.url).href)};
    const store = new Store(${JSON.stringify(dir)});
    const raw = store.db;
    store.db = new Proxy(raw, { get(target, key) {
      if (key === 'prepare') return sql => sql.startsWith('UPDATE runs SET body') ? { run() { process.kill(process.pid, 'SIGKILL'); } } : target.prepare(sql);
      const value = Reflect.get(target, key, target);
      return typeof value === 'function' ? value.bind(target) : value;
    } });
    store.updateRun(${JSON.stringify(run.id)}, r => { r.nodes.a.status = 'completed'; r.outputs.a = { v: 2 }; r.nodes.b = { status: 'new' }; r.steps = 2; }, { type: 'probe.killed' });
  `;
  const child = spawnSync(process.execPath, ['--input-type=module', '--eval', source], { env: { PATH: process.env.PATH, NODE_NO_WARNINGS: '1' }, timeout: 10000, encoding: 'utf8' });
  assert.equal(child.signal, 'SIGKILL', child.stderr);
  const reopened = new Store(dir);
  try {
    assert.deepEqual(reopened.run(run.id), before.record, 'rows, header and size are as before');
    assert.deepEqual(reopened.events(run.id), before.events, 'and so is the chain');
    assert.equal(reopened.updateRun(run.id, r => { r.nodes.a.status = 'completed'; }, { type: 'probe.after' }).nodes.a.status, 'completed', 'and it can carry on');
    assert.equal(reopened.events(run.id).length, before.events.length + 1);
  } finally { reopened.close(); }
});

test('atomicity: a checkpoint head that disagrees with the chain still refuses the append', t => {
  const { store, run } = environment(t, chain(1));
  store.updateRun(run.id, r => { r.steps = 1; }, { type: 'probe.one' });
  store.db.prepare('DELETE FROM events WHERE run_id=? AND seq=2').run(run.id); // a hole in the middle: the tail is still there
  assert.throws(() => store.updateRun(run.id, () => {}, { type: 'probe.two' }), { code: 'CORRUPT_EVENTS' });
  store.db.prepare('DELETE FROM events WHERE run_id=? AND seq=3').run(run.id); // the tail
  assert.throws(() => store.updateRun(run.id, () => {}, { type: 'probe.three' }), { code: 'CORRUPT_EVENTS' });
});

// ---- cost -------------------------------------------------------------------------------------------------------------------------------------
const cpu = fn => { const start = process.cpuUsage(); fn(); const used = process.cpuUsage(start); return (used.user + used.system) / 1000; };
test('cost: the cost of an update does not grow with the size of the run', t => {
  const { store, run } = environment(t, chain(1));
  store.db.exec('PRAGMA synchronous=OFF'); // the commit is the same whatever the run holds; leave it out of a CPU measurement
  const update = i => store.updateRun(run.id, r => { r.nodes[`n${i % 20}`] = { status: 'completed', i }; r.outputs[`n${i % 20}`] = { value: i }; }, { type: 'probe.step', i }, { result: 'header' });
  const measure = () => { const samples = []; for (let round = 0; round < 3; round++) samples.push(cpu(() => { for (let i = 0; i < 150; i++) update(i); })); return samples.sort((a, b) => a - b)[1]; };
  update(0); const small = measure();
  store.updateRun(run.id, r => { for (let i = 0; i < 6000; i++) { r.nodes[`bulk${i}`] = { status: 'completed', kind: 'task', attempts: 1, note: 'x'.repeat(40) }; r.outputs[`bulk${i}`] = { value: i, text: 'y'.repeat(60) }; } }, { type: 'probe.bulk' });
  assert.ok(store.db.prepare('SELECT bytes FROM runs WHERE id=?').get(run.id).bytes > 900000, 'about a megabyte of state');
  const large = measure();
  // The whole-run store cost 3 ms at 2 KB of state and 33 ms at 929 KB (04-efficiency-rust.md section 3.2), a factor of 11; allow 3.
  assert.ok(large < small * 3 + 20, `an update of a 1 MB run took ${large.toFixed(0)} ms of CPU per 150, one of a small run ${small.toFixed(0)} ms`);
});

test('cost: the runtime loop reads only the rows it needs, never the whole record, and the run is reconstructed exactly once', async t => {
  const workflow = base([echo('first'), { id: 'each', kind: 'map', needs: ['first'], description: 'map', items: ref('input.items'), maxItems: 40, concurrency: 4,
    body: { nodes: [echo('w', { value: ref('item') })], acceptance: [{ op: 'exists', value: ref('nodes.w.value') }] } }], [{ op: 'eq', left: ref('nodes.each.count'), right: 30 }]);
  const { store, runtime, run } = environment(t, workflow, { items: Array.from({ length: 30 }, (_, i) => i) });
  let whole = 0; const original = store.rows.run.bind(store.rows);
  store.rows.run = id => { whole++; return original(id); };
  const result = await runtime.execute(run.id);
  assert.equal(result.status, 'succeeded');
  assert.ok(whole <= 2, `the whole run was assembled ${whole} times (once to check it on resume, once to return it)`);
  assert.equal(result.outputs.each.count, 30);
});

test('cost: a chain of nodes costs the same per node at 20 nodes and at 200', async t => {
  const perNode = async n => {
    const { store, runtime, run } = environment(t, chain(n));
    store.db.exec('PRAGMA synchronous=OFF');
    const start = process.cpuUsage(); const result = await runtime.execute(run.id); const used = process.cpuUsage(start);
    assert.equal(result.status, 'succeeded');
    return (used.user + used.system) / 1000 / n;
  };
  await perNode(20); // warm up
  const few = await perNode(20), many = await perNode(200);
  // The whole-run store went from 3 ms per node at 10-100 nodes to 16-18 ms at 500; a node must not cost more because the run is bigger.
  assert.ok(many < few * 2.5 + 1, `${many.toFixed(2)} ms of CPU per node at 200 nodes, ${few.toFixed(2)} at 20`);
});

test('digest: the record a run is stored as has the digest the whole-run store gave it (outcome receipts bind it)', async t => {
  const { store, runtime, run } = environment(t, chain(3));
  const finished = await runtime.execute(run.id);
  assert.equal(digest(store.run(run.id)), digest(finished));
  assert.equal(digest(JSON.parse(JSON.stringify(finished))), digest(finished));
});
